B=[
('الْمَلِكُ وَالْفَيْلَسُوفُ','Kral ve filozof',[
('قَالَ دَبْشَلِيمُ الْمَلِكُ لِبَيْدَبَا الْفَيْلَسُوفِ: «قَدْ سَمِعْتُ مَثَلَ الْمُتَحَابَّيْنِ اللَّذَيْنِ فَرَّقَ بَيْنَهُمَا الْكَذُوبُ.»','Kral Debşelîm filozof Beydebâ’ya dedi ki: “Yalancının arasını açtığı iki sevenin misalini dinledim.”'),
('«فَحَدِّثْنِي الْآنَ عَنْ إِخْوَانِ الصَّفَاءِ: كَيْفَ يَبْدَأُ تَوَاصُلُهُمْ، وَكَيْفَ يَنْتَفِعُ بَعْضُهُمْ بِبَعْضٍ؟»','“Şimdi bana halis dostlardan söz et: Bağları nasıl başlar ve birbirlerinden nasıl faydalanırlar?”'),
('قَالَ الْفَيْلَسُوفُ: «أَيُّهَا الْمَلِكُ، إِنَّ الْعَاقِلَ لَا يَعْدِلُ بِالْإِخْوَانِ شَيْئًا.»','Filozof dedi ki: “Ey kral, akıllı kişi hiçbir şeyi dostlara denk tutmaz.”'),
('«فَالْإِخْوَانُ هُمُ الْأَعْوَانُ عَلَى الْخَيْرِ، وَالْمُوَاسُونَ عِنْدَ الْمَصَائِبِ.»','“Çünkü dostlar hayırda yardımcılar, musibetlerde teselli edenlerdir.”'),
('«وَمِنْ أَمْثَالِ ذَلِكَ مَثَلُ الْحَمَامَةِ الْمُطَوَّقَةِ وَالْجُرَذِ وَالظَّبْيِ وَالْغُرَابِ.»','“Bunun misallerinden biri halkalı güvercin, fare, ceylan ve karganın misalidir.”'),
('قَالَ الْمَلِكُ: «وَكَيْفَ كَانَ ذَلِكَ؟»','Kral dedi ki: “O nasıl oldu?”')]),
('الشَّجَرَةُ وَالصَّيَّادُ','Ağaç ve avcı',[
('قَالَ بَيْدَبَا: «زَعَمُوا أَنَّهُ كَانَ بِأَرْضِ سَكَاوَنْدَ جِينَ مَكَانٌ كَثِيرُ الصَّيْدِ.»','Beydebâ dedi ki: “Derler ki Sekâvendcîn diyarında avı bol bir yer vardı.”'),
('«وَكَانَ فِيهِ شَجَرَةٌ كَثِيرَةُ الْأَغْصَانِ، مُلْتَفَّةُ الْوَرَقِ، فِيهَا وَكْرُ غُرَابٍ.»','“Orada dalları çok, yaprakları sık bir ağaç vardı; onda bir karganın yuvası bulunuyordu.”'),
('«فَبَيْنَمَا الْغُرَابُ ذَاتَ يَوْمٍ سَاقِطٌ فِي وَكْرِهِ، إِذْ بَصُرَ بِصَيَّادٍ قَبِيحِ الْمَنْظَرِ.»','“Bir gün karga yuvasında otururken çirkin görünüşlü bir avcı gördü.”'),
('«كَانَ عَلَى عَاتِقِهِ شَبَكَةٌ، وَفِي يَدِهِ عَصًا، وَهُوَ مُقْبِلٌ نَحْوَ الشَّجَرَةِ.»','“Omzunda bir ağ, elinde bir değnek vardı ve ağaca doğru geliyordu.”'),
('«فَذُعِرَ مِنْهُ الْغُرَابُ وَقَالَ: لَقَدْ سَاقَ هَذَا الرَّجُلَ إِلَى هُنَا أَمْرٌ؛ إِمَّا حَيْنِي وَإِمَّا حَيْنُ غَيْرِي.»','“Karga ondan korktu ve dedi ki: Bu adamı buraya bir iş getirdi; ya benim ölümüm ya başkasının ölümü.”'),
('«فَلَأَثْبُتَنَّ مَكَانِي حَتَّى أَنْظُرَ مَاذَا يَصْنَعُ.»','“Yerimde durup ne yapacağına bakacağım.”'),
('«فَنَصَبَ الصَّيَّادُ شَبَكَتَهُ، وَنَثَرَ عَلَيْهَا الْحَبَّ، وَكَمَنَ قَرِيبًا مِنْهَا.»','“Avcı ağını kurdu, üzerine tane serpti ve yakınında pusuya yattı.”')]),
('الْوُقُوعُ فِي الشَّبَكَةِ','Ağa düşüş',[
('«فَلَمْ يَلْبَثْ إِلَّا قَلِيلًا حَتَّى مَرَّتْ بِهِ حَمَامَةٌ يُقَالُ لَهَا الْمُطَوَّقَةُ.»','“Çok geçmeden oradan, adına Halkalı denen bir güvercin geçti.”'),
('«وَكَانَتْ سَيِّدَةَ الْحَمَامِ، وَمَعَهَا حَمَامٌ كَثِيرٌ.»','“Güvercinlerin başkanıydı ve yanında birçok güvercin vardı.”'),
('«فَعَمِيَتْ هِيَ وَأَصْحَابُهَا عَنِ الشَّرَكِ، فَوَقَعْنَ عَلَى الْحَبِّ يَلْتَقِطْنَهُ.»','“O ve arkadaşları tuzağı görmediler ve taneleri toplamak için üzerine kondular.”'),
('«فَعَلِقْنَ فِي الشَّبَكَةِ كُلُّهُنَّ.»','“Hepsi ağa takıldı.”'),
('«وَأَقْبَلَ الصَّيَّادُ فَرِحًا مَسْرُورًا.»','“Avcı sevinçli ve mutlu bir hâlde yaklaştı.”'),
('«فَجَعَلَتْ كُلُّ حَمَامَةٍ تَضْطَرِبُ فِي حِبَالَتِهَا، وَتَلْتَمِسُ الْخَلَاصَ لِنَفْسِهَا.»','“Her güvercin kendi ipinde çırpınmaya ve kendisi için kurtuluş aramaya başladı.”'),
('«فَقَالَتِ الْمُطَوَّقَةُ: لَا تَتَخَاذَلْنَ فِي الْمُعَالَجَةِ، وَلَا تَكُنْ نَفْسُ إِحْدَاكُنَّ أَهَمَّ إِلَيْهَا مِنْ نَفْسِ صَاحِبَتِهَا.»','“Halkalı dedi ki: Çabalamada birbirinizi yalnız bırakmayın; hiçbirinizin canı arkadaşının canından daha önemli olmasın.”')]),
('قُوَّةُ الْجَمَاعَةِ','Topluluğun gücü',[
('«وَلَكِنْ نَتَعَاوَنُ جَمِيعًا، فَنَقْتَلِعُ الشَّبَكَةَ، فَيَنْجُو بَعْضُنَا بِبَعْضٍ.»','“Ama hepimiz yardımlaşalım; ağı söküp çıkaralım ve birbirimizle kurtulalım.”'),
('«فَتَعَاوَنَّ جَمِيعًا، وَطِرْنَ طَيَرَانًا وَاحِدًا، فَاقْتَلَعْنَ الشَّبَكَةَ.»','“Hepsi yardımlaştı, tek bir uçuşla havalandılar ve ağı söküp çıkardılar.”'),
('«وَعَلَوْنَ بِهَا فِي جَوِّ السَّمَاءِ.»','“Onunla birlikte göğün boşluğuna yükseldiler.”'),
('«فَلَمْ يَقْطَعِ الصَّيَّادُ رَجَاءَهُ مِنْهُنَّ، وَظَنَّ أَنَّهُنَّ لَا يُجَاوِزْنَ إِلَّا قَرِيبًا وَيَقَعْنَ.»','“Avcı onlardan ümidini kesmedi; az bir mesafe gidip düşeceklerini sandı.”'),
('«فَتَبِعَهُنَّ يَنْظُرُ إِلَيْهِنَّ.»','“Onlara bakarak peşlerinden gitti.”'),
('«فَقَالَ الْغُرَابُ: لَأَتْبَعَنَّهُنَّ حَتَّى أَنْظُرَ مَا يَكُونُ مِنْهُنَّ.»','“Karga dedi ki: Onlardan ne olacağını görünceye kadar peşlerinden gideceğim.”')]),
('حِيلَةُ الْمُطَوَّقَةِ','Halkalının hilesi',[
('«فَالْتَفَتَتِ الْمُطَوَّقَةُ، فَرَأَتِ الصَّيَّادَ يَتْبَعُهُنَّ.»','“Halkalı dönüp baktı ve avcının peşlerinden geldiğini gördü.”'),
('«فَقَالَتْ لِلْحَمَامِ: هَذَا الصَّيَّادُ مُجِدٌّ فِي طَلَبِكُنَّ.»','“Güvercinlere dedi ki: Bu avcı sizi aramakta kararlı.”'),
('«فَإِنْ نَحْنُ أَخَذْنَا فِي الْفَضَاءِ لَمْ يَخْفَ عَلَيْهِ أَمْرُنَا، وَلَمْ يَزَلْ يَتْبَعُنَا.»','“Açık yerde gidersek durumumuz ondan gizli kalmaz ve peşimizi bırakmaz.”'),
('«وَإِنْ نَحْنُ تَوَجَّهْنَا إِلَى الْعُمْرَانِ وَالْأَشْجَارِ خَفِيَ عَلَيْهِ أَمْرُنَا، فَيَنْصَرِفُ.»','“Ama meskûn yerlere ve ağaçlara yönelirsek durumumuz ondan gizlenir ve döner gider.”'),
('«وَبِمَكَانِ كَذَا جُرَذٌ هُوَ لِي أَخٌ، فَلَوِ انْتَهَيْنَا إِلَيْهِ قَطَعَ عَنَّا هَذَا الشَّرَكَ.»','“Falanca yerde benim kardeşim olan bir fare var; ona varırsak bu tuzağı üstümüzden keser.”'),
('«فَفَعَلْنَ ذَلِكَ، وَخَفِيَ أَمْرُهُنَّ عَلَى الصَّيَّادِ، فَيَئِسَ مِنْهُنَّ وَانْصَرَفَ.»','“Öyle yaptılar; durumları avcıdan gizlendi, avcı onlardan ümidini kesip döndü.”'),
('«وَتَبِعَهُنَّ الْغُرَابُ لِيَعْلَمَ حِيلَتَهُنَّ، فَيَتَّخِذَهَا عُدَّةً لِنَفْسِهِ.»','“Karga onların hilesini öğrenmek ve onu kendisi için bir hazırlık edinmek için peşlerinden gitti.”')]),
('زِيرَكُ الْجُرَذُ','Fare Zîrek',[
('«فَلَمَّا انْتَهَتِ الْمُطَوَّقَةُ إِلَى الْجُرَذِ، أَمَرَتِ الْحَمَامَ أَنْ يَسْقُطْنَ.»','“Halkalı fareye varınca güvercinlere konmalarını emretti.”'),
('«وَكَانَ لِلْجُرَذِ مِائَةُ جُحْرٍ لِلْمَخَاوِفِ، وَاسْمُهُ زِيرَكُ.»','“Farenin korkulu anlar için yüz deliği vardı; adı Zîrek’ti.”'),
('«فَنَادَتْهُ الْمُطَوَّقَةُ بِاسْمِهِ: يَا زِيرَكُ!»','“Halkalı onu adıyla çağırdı: Ey Zîrek!”'),
('«فَأَجَابَهَا مِنْ جُحْرِهِ: مَنْ أَنْتِ؟ قَالَتْ: أَنَا خَلِيلَتُكَ الْمُطَوَّقَةُ.»','“Deliğinden ona cevap verdi: Sen kimsin? Dedi ki: Ben dostun Halkalı’yım.”'),
('«فَأَقْبَلَ إِلَيْهَا الْجُرَذُ يَسْعَى، فَلَمَّا رَآهَا فِي الشَّبَكَةِ قَالَ: مَا أَوْقَعَكِ فِي هَذِهِ الْوَرْطَةِ وَأَنْتِ مِنَ الْأَكْيَاسِ؟»','“Fare koşarak ona geldi; onu ağda görünce dedi ki: Sen akıllılardan olduğun hâlde seni bu çıkmaza ne düşürdü?”'),
('«قَالَتْ: أَلَمْ تَعْلَمْ أَنَّهُ لَيْسَ مِنَ الْخَيْرِ وَالشَّرِّ شَيْءٌ إِلَّا وَهُوَ مُقَدَّرٌ عَلَى مَنْ تُصِيبُهُ الْمَقَادِيرُ؟»','“Dedi ki: Bilmez misin, iyilik ve kötülükten hiçbir şey yoktur ki kaderin isabet ettiği kişiye takdir edilmiş olmasın?”'),
('«فَالْقَدَرُ هُوَ الَّذِي أَرَانِي الْحَبَّ، وَأَعْمَى بَصَرِي عَنِ الشَّبَكَةِ.»','“Bana taneyi gösteren ve gözümü ağdan kör eden kaderdir.”')]),
('الْوَفَاءُ','Vefa',[
('«ثُمَّ أَخَذَ الْجُرَذُ فِي قَرْضِ الْعُقَدِ الَّتِي فِيهَا الْمُطَوَّقَةُ.»','“Sonra fare, Halkalı’nın içinde bulunduğu düğümleri kemirmeye başladı.”'),
('«فَقَالَتْ لَهُ: ابْدَأْ بِقَطْعِ عُقَدِ سَائِرِ الْحَمَامِ، وَبَعْدَ ذَلِكَ أَقْبِلْ عَلَى عُقَدِي.»','“Ona dedi ki: Önce diğer güvercinlerin düğümlerini kesmekle başla, sonra benim düğümlerime yönel.”'),
('«فَأَعَادَتْ ذَلِكَ عَلَيْهِ مِرَارًا، وَهُوَ لَا يَلْتَفِتُ إِلَى قَوْلِهَا.»','“Bunu ona defalarca tekrarladı, o ise sözüne kulak asmıyordu.”'),
('«فَلَمَّا أَكْثَرَتْ عَلَيْهِ قَالَ: لَقَدْ كَرَّرْتِ الْقَوْلَ كَأَنَّكِ لَيْسَ لَكِ فِي نَفْسِكِ حَاجَةٌ!»','“Israr edince dedi ki: Sözü öyle tekrarladın ki sanki kendi canına hiç ihtiyacın yok!”'),
('«قَالَتْ: إِنِّي أَخَافُ إِنْ أَنْتَ بَدَأْتَ بِعُقَدِي أَنْ تَمَلَّ وَتَكْسَلَ عَنْ بَعْضِ مَا بَقِيَ.»','“Dedi ki: Benim düğümlerimden başlarsan bıkıp geri kalanların bazısında üşenmenden korkarım.”'),
('«وَعَرَفْتُ أَنَّكَ إِنْ بَدَأْتَ بِهِنَّ وَكُنْتُ أَنَا الْأَخِيرَةَ، لَمْ تَرْضَ أَنْ تَتْرُكَنِي.»','“Ve bildim ki onlardan başlarsan ve ben sonuncu olursam beni bırakmaya razı olmazsın.”'),
('«قَالَ الْجُرَذُ: هَذَا مِمَّا يَزِيدُ الرَّغْبَةَ وَالْمَوَدَّةَ فِيكِ.»','“Fare dedi ki: Bu, sana olan arzuyu ve sevgiyi artıran şeylerdendir.”'),
('«ثُمَّ قَطَعَ الشَّبَكَةَ كُلَّهَا، فَانْطَلَقَتِ الْمُطَوَّقَةُ وَحَمَامُهَا آمِنَاتٍ.»','“Sonra ağın hepsini kesti; Halkalı ve güvercinleri emniyet içinde uçup gittiler.”')]),
]
